<?php page_header('Find your carrier');page_intro('US PREPAID NETWORKS','Your carrier is right here.','Explore prepaid refill options for your existing US mobile number.');$carriers=all('SELECT * FROM carriers WHERE active=1 ORDER BY sort_order,name'); ?>
<section class="container section compact"><label class="search-field" for="carrier-search"><?=icon('search')?><input id="carrier-search" type="search" placeholder="Search carriers" aria-label="Search carriers" autocomplete="off"></label><div class="carrier-grid directory"><?php foreach($carriers as $c):?><a class="carrier-card" data-carrier="<?=e(strtolower($c['name']))?>" href="/carriers/<?=e($c['slug'])?>"><?=carrier_logo($c)?><strong class="carrier-name"><?=e($c['name'])?></strong><span>View refill options <?=icon('arrow')?></span></a><?php endforeach;?></div><p id="no-carriers" class="empty-state" hidden>No matching carrier. Try another name or <a href="/contact">contact us</a>.</p><p class="section-note">Some carriers have account or plan restrictions. Check compatibility before placing an order.</p></section><?php page_footer(); ?>
